code_comparison.code:

enum WithoutDebugInfo: string {
    case Bar = "Baz";

    <em>public function __call()</em> {
        // Code for the magic method.
    }
}


enum WithDebugInfo: string {
    case Bar = "Baz";

    <em>public function __debugInfo()</em> {
        return [
            __CLASS__ . '::' . $this->name
            . ' = ' . $this->value
        ];
    }
}
